          "sql": "SELECT c.attr_http_response_status_code client_code, c.attr_status_code client_status, s.attr_http_response_status_code server_code, s.attr_status_code server_status, s.span_name, COUNT(*) n FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.service_name='ts-travel2-service' AND c.attr_span_kind='Client' AND s.service_name='ts-seat-service' GROUP BY ALL ORDER BY n DESC",
          "claim": "Travel2 client sees 503 on 1,804 calls to seat left_tickets, while seat's server spans for those same calls return 200."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_http_response_status_code code, COUNT(*) n FROM normal_traces WHERE service_name='ts-travel2-service' AND attr_span_kind='Client' AND span_name='POST' GROUP BY ALL ORDER BY n DESC",
          "claim": "In the normal period, all of travel2's outgoing POST client spans returned status 200."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, attr_http_response_status_code code, COUNT(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND attr_span_kind='Server' AND span_name LIKE '%trip%' GROUP BY ALL ORDER BY n DESC",
          "claim": "Travel2's trip_detail and trips/left server endpoints return 500 for almost every request in the incident period."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, c.attr_http_response_status_code code, s.service_name callee, COUNT(*) n, quantile_cont(c.duration,0.5)/1e6 caller_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.service_name='ts-route-plan-service' AND c.attr_span_kind='Client' AND s.service_name='ts-travel2-service' GROUP BY ALL ORDER BY n DESC",
          "claim": "Route-plan's POST calls to travel2 return 500 with p50 around 4.6 s, versus about 9 ms when they succeed."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code code, COUNT(*) n, quantile_cont(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Client' GROUP BY ALL ORDER BY n DESC",
          "claim": "Travel-plan's calls to route-plan time out: 504 responses with p50 around 60 s, plus some successes."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, quantile_cont(duration,0.95)/1e6 p95_ms, SUM(CASE WHEN attr_http_response_status_code >= 500 THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Client' AND span_name LIKE '%travel%' GROUP BY ALL ORDER BY n DESC",
          "claim": "Ui-dashboard's calls to travel-plan show p95 latency in the tens of seconds with 5xx errors."
        }
      ]
    }
  ]
}
